const PreviewPane = ({
  app,
  result,
  authorName,
}: {
  app: App;
  result: SearchResultRow | undefined;
  authorName: string;
}): ReactElement => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  // Paired with its file so an in-flight read can't put one note's body under
  // another note's title.
  const [loaded, setLoaded] = useState<{ file: TFile; text: string } | null>(
    null,
  );
  const [renderedFile, setRenderedFile] = useState<TFile | null>(null);

  const file = result?.file;

  useEffect(() => {
    if (!file) {
      setLoaded(null);
      return;
    }
    let cancelled = false;
    void app.vault.cachedRead(file).then((text) => {
      if (!cancelled) setLoaded({ file, text });
    });
    return () => {
      cancelled = true;
    };
  }, [app, file]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !file || loaded?.file !== file) return;

    container.empty();
    setRenderedFile(null);
    const component = new Component();
    let cancelled = false;
    void (async () => {
      await MarkdownRenderer.render(
        app,
        loaded.text.trim() || "This note is empty.",
        container,
        file.path,
        component,
      );
      await waitForImages(container);
      if (!cancelled) setRenderedFile(file);
    })();

    return () => {
      cancelled = true;
      component.unload();
      container.empty();
    };
  }, [app, file, loaded]);

  // Separate from rendering, so moving between two lines of one note only re-scrolls.
  const taggedLine = result?.tagLine?.line;
  useEffect(() => {
    const container = containerRef.current;
    // `loaded` still holds the previous note until the new file's read finishes.
    if (!container || !loaded || !file || renderedFile !== file) return;

    const target =
      taggedLine === undefined
        ? null
        : findTaggedLineElement({
            container,
            cache: app.metadataCache.getFileCache(file),
            text: loaded.text,
            line: taggedLine,
          });
    // Same-note switches don't re-render, so an unlocated line would keep the last scroll.
    if (!target) {
      container.scrollTop = 0;
      return;
    }
    target.scrollIntoView({ block: "center" });
    target.addClass(PREVIEW_FLASH_CLASS);
    const clearFlash = (): void => target.removeClass(PREVIEW_FLASH_CLASS);
    target.addEventListener("animationend", clearFlash, { once: true });
    return () => {
      target.removeEventListener("animationend", clearFlash);
      clearFlash();
    };
  }, [app, file, loaded, renderedFile, taggedLine]);

  if (!result || !file) {
    return (
      <div className="text-muted flex flex-1 items-center justify-center">
        Select a result to preview it.
      </div>
    );
  }

  return (
    <div className="flex flex-1 flex-col overflow-hidden">
      <div className="border-modifier-border border-b px-4 py-3">
        <div className="text-normal font-semibold">{result.title}</div>
        <div className="text-muted mt-1 text-xs">
          {`Created ${formatTimestamp(file.stat.ctime)} · Modified ${formatTimestamp(
            file.stat.mtime,
          )} · ${authorName}`}
        </div>
      </div>
      <div
        ref={containerRef}
        className="text-normal flex-1 overflow-y-auto px-4 py-3"
      />
    </div>
  );
};

const HighlightedTitle = ({
  title,
  match,
}: {
  title: string;
  match: SearchResult;
}): ReactElement => {
